from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    sums = {}
    bests = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    grid_width = width * cell_size
    grid_height = height * cell_size
    total_cells = width * height
    for obs in observations:
        if (
            not isinstance(obs, dict)
            or "x" not in obs or not isinstance(obs["x"], int)
            or "y" not in obs or not isinstance(obs["y"], int)
            or "value" not in obs or not isinstance(obs["value"], int)
            or "quality" not in obs or not isinstance(obs["quality"], int)
            or not 0 <= obs["quality"] <= 100
        ):
            return {"ok": False, "error": "bad observation"}

        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        x = obs["x"]
        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            if x - grid_width < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        y = obs["y"]
        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row >= height:
            if y - grid_height < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        if key not in bests or obs["value"] > bests[key]:
            bests[key] = obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    if mode == "max":
        cells = _max_rows(bests, counts, width, height, raw["fill_value"])
    else:
        cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _max_rows(bests: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(bests[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

from typing import Optional

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_FIELDS: tuple[str, ...] = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    payload, error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    grid, observations, fill_value, mode = payload

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    tolerance = cell_size // 2
    accumulator = _Accumulator(width, height, cell_size, tolerance)

    for obs in observations:
        error = accumulator.record(obs)
        if error is not None:
            return {"ok": False, "error": error}

    stats = accumulator.stats
    cells = _summarized_rows(accumulator.sums, accumulator.maxes, accumulator.counts,
                             width, height, fill_value, mode)
    flags = _flag_rows(accumulator.counts, accumulator.degraded, width, height)
    coverage = _coverage(accumulator.counts, width, height)
    line = _summary_line(width * height, len(accumulator.counts),
                         stats.dropped, stats.rejected, stats.saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": stats.dropped,
        "rejected": stats.rejected,
        "saturated": stats.saturated,
        "coverage": coverage,
        "line": line,
    }


class _Accumulator:
    def __init__(self, width: int, height: int, cell_size: int, tolerance: int) -> None:
        self.sums: dict = {}
        self.maxes: dict = {}
        self.counts: dict = {}
        self.degraded: dict = {}
        self.stats = _Stats()
        self.width = width
        self.height = height
        self.cell_size = cell_size
        self.tolerance = tolerance

    def record(self, obs: object) -> Optional[str]:
        valid, error = _validate_observation(obs)
        if not valid:
            return error
        if obs["quality"] < MIN_QUALITY:
            self.stats.rejected += 1
            return None

        col = _bucket_index(obs["x"], self.cell_size, self.width, self.tolerance)
        if col is None:
            self.stats.dropped += 1
            return None

        row = _bucket_index(obs["y"], self.cell_size, self.height, self.tolerance)
        if row is None:
            self.stats.dropped += 1
            return None

        key = (row, col)
        current = self.counts.get(key, 0)
        if current >= SATURATION_LIMIT:
            self.stats.saturated += 1
            return None
        self.sums[key] = self.sums.get(key, 0) + obs["value"]
        self.maxes[key] = max(self.maxes.get(key, obs["value"]), obs["value"])
        self.counts[key] = current + 1
        if obs["quality"] < GOOD_QUALITY:
            self.degraded[key] = True
        return None


class _Stats:
    def __init__(self) -> None:
        self.dropped = 0
        self.rejected = 0
        self.saturated = 0


def _validate_input(raw: object) -> tuple[Optional[tuple[dict, list, int, str]], Optional[str]]:
    if not isinstance(raw, dict):
        return None, "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return None, "missing field"
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return None, "bad mode"
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return None, "bad grid"
    for error, ok in (
        ("bad grid", "width" in grid and "height" in grid and "cell_size" in grid),
        ("bad width", isinstance(grid.get("width"), int) and 1 <= grid["width"] <= MAX_DIM),
        ("bad height", isinstance(grid.get("height"), int) and 1 <= grid["height"] <= MAX_DIM),
        ("bad cell size", isinstance(grid.get("cell_size"), int) and grid["cell_size"] >= 1),
    ):
        if not ok:
            return None, error
    if not isinstance(raw["fill_value"], int):
        return None, "bad fill value"
    observations = raw["observations"]
    if not isinstance(observations, list):
        return None, "bad observations"
    return (grid, observations, raw["fill_value"], mode), None


def _validate_observation(obs: object) -> tuple[bool, Optional[str]]:
    if not isinstance(obs, dict) or not all(
        field in obs and isinstance(obs[field], int) for field in _FIELDS
    ):
        return False, "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return False, "bad observation"
    return True, None


def _bucket_index(coord: int, cell_size: int, limit: int, tolerance: int) -> Optional[int]:
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= limit:
        if coord - limit * cell_size < tolerance:
            index = limit - 1
        else:
            return None
    return index


def _summarized_rows(sums: dict, maxes: dict, counts: dict, width: int, height: int,
                     fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "max":
                    cells.append(maxes[key])
                else:
                    cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_ERR_MALFORMED = "malformed input"
_ERR_MISSING = "missing field"
_ERR_GRID = "bad grid"
_ERR_WIDTH = "bad width"
_ERR_HEIGHT = "bad height"
_ERR_CELL_SIZE = "bad cell size"
_ERR_FILL = "bad fill value"
_ERR_OBSERVATIONS = "bad observations"
_ERR_OBSERVATION = "bad observation"
_ERR_MODE = "bad mode"

_MODES = ("mean", "max")

_ERR = "error"
_OK = "ok"


def accumulate_grid(raw: object) -> dict:
    error = _validate_payload(raw)
    if error is not None:
        return _fail(error)

    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = raw["fill_value"]
    mode = raw.get("mode", "mean")

    if not _valid_observations(raw["observations"]):
        return _fail(_ERR_OBSERVATION)

    sums, counts, maxes, degraded = {}, {}, {}, {}
    dropped = rejected = saturated = 0
    tolerance = cell_size // 2

    for obs in raw["observations"]:
        action = _classify(obs, width, height, cell_size, tolerance, sums, counts, maxes, degraded)
        if action == "reject":
            rejected += 1
        elif action == "drop":
            dropped += 1
        elif action == "saturate":
            saturated += 1

    total_cells = width * height
    coverage = _coverage(len(counts), total_cells)
    cells = _build_cells(sums, counts, maxes, width, height, fill_value, mode)
    flags = _build_flags(counts, degraded, width, height)
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)

    return {
        _OK: True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _fail(message: str) -> dict:
    return {_OK: False, _ERR: message}


def _validate_payload(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return _ERR_MALFORMED
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return _ERR_MISSING
    return _first(
        _grid_errors(raw["grid"]),
        _int_error(raw, "fill_value", _ERR_FILL),
        _list_error(raw, "observations", _ERR_OBSERVATIONS),
        _mode_error(raw),
    )


def _first(*guards: str | None) -> str | None:
    for guard in guards:
        if guard is not None:
            return guard
    return None


def _grid_errors(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return _ERR_GRID
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return _ERR_GRID
    return _first(
        _bounded_error(grid, "width", _ERR_WIDTH, 1, MAX_DIM),
        _bounded_error(grid, "height", _ERR_HEIGHT, 1, MAX_DIM),
        _positive_error(grid, "cell_size", _ERR_CELL_SIZE),
    )


def _bounded_error(grid: dict, field: str, error: str, low: int, high: int) -> str | None:
    value = grid[field]
    if not isinstance(value, int) or value < low or value > high:
        return error
    return None


def _positive_error(grid: dict, field: str, error: str) -> str | None:
    value = grid[field]
    if not isinstance(value, int) or value < 1:
        return error
    return None


def _int_error(raw: dict, field: str, error: str) -> str | None:
    if not isinstance(raw[field], int):
        return error
    return None


def _list_error(raw: dict, field: str, error: str) -> str | None:
    if not isinstance(raw[field], list):
        return error
    return None


def _mode_error(raw: dict) -> str | None:
    mode = raw.get("mode", "mean")
    if not isinstance(mode, str) or mode not in _MODES:
        return _ERR_MODE
    return None


def _valid_observations(observations: list) -> bool:
    for obs in observations:
        if not isinstance(obs, dict):
            return False
        for field in ("x", "y", "value", "quality"):
            if field not in obs or not isinstance(obs[field], int):
                return False
        if not 0 <= obs["quality"] <= 100:
            return False
    return True


def _classify(
    obs: dict,
    width: int,
    height: int,
    cell_size: int,
    tolerance: int,
    sums: dict,
    counts: dict,
    maxes: dict,
    degraded: dict,
) -> str:
    if obs["quality"] < MIN_QUALITY:
        return "reject"

    col, drop_x = _snap(obs["x"], width, cell_size, tolerance)
    row, drop_y = _snap(obs["y"], height, cell_size, tolerance)
    if drop_x or drop_y:
        return "drop"

    key = (row, col)
    if counts.get(key, 0) >= SATURATION_LIMIT:
        return "saturate"
    sums[key] = sums.get(key, 0) + obs["value"]
    maxes[key] = max(maxes.get(key, obs["value"]), obs["value"])
    counts[key] = counts.get(key, 0) + 1
    if obs["quality"] < GOOD_QUALITY:
        degraded[key] = True
    return "accept"


def _snap(axis: int, limit: int, cell_size: int, tolerance: int) -> tuple[int, bool]:
    if axis < 0:
        return 0, True
    index = axis // cell_size
    if index >= limit:
        if axis - limit * cell_size < tolerance:
            return limit - 1, False
        return 0, True
    return index, False


def _build_cells(sums: dict, counts: dict, maxes: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = [fill_value] * width
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "max":
                    cells[col] = maxes[key]
                else:
                    cells[col] = sums[key] // counts[key]
        rows.append(cells)
    return rows


def _build_flags(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = ["empty"] * width
        for col in range(width):
            key = (row, col)
            if key in counts:
                flags[col] = "degraded" if key in degraded else "good"
        rows.append(flags)
    return rows


def _coverage(filled: int, total_cells: int) -> int:
    return filled * 100 // total_cells


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object, mode: str = "mean") -> dict:
    if mode not in ("mean", "max"):
        return {"ok": False, "error": "bad mode"}

    grid = _validate_input(raw)
    if not isinstance(grid, dict):
        return {"ok": False, "error": grid}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = grid["fill_value"]
    tolerance = cell_size // 2

    sums = {}
    maxes = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in grid["observations"]:
        if not _valid_observation(obs):
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin_x(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped += 1
            continue

        row = _bin_y(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        if mode == "mean":
            sums[key] = sums.get(key, 0) + obs["value"]
        else:
            if key not in maxes or obs["value"] > maxes[key]:
                maxes[key] = obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    if mode == "mean":
        cells = _averaged_rows(sums, counts, width, height, fill_value)
    else:
        cells = _max_rows(maxes, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_input(raw: object) -> dict | str:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]

    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"

    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"

    return grid | {"fill_value": raw["fill_value"], "observations": observations}


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    if not isinstance(obs.get("x"), int):
        return False
    if not isinstance(obs.get("y"), int):
        return False
    if not isinstance(obs.get("value"), int):
        return False
    quality = obs.get("quality")
    return isinstance(quality, int) and 0 <= quality <= 100


def _bin_x(x: int, width: int, cell_size: int, tolerance: int) -> int | None:
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            return width - 1
        return None
    return col


def _bin_y(y: int, height: int, cell_size: int, tolerance: int) -> int | None:
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            return height - 1
        return None
    return row


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _max_rows(maxes: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(maxes[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

