from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}

    grid = raw["grid"]
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]
    mode = raw.get("mode", "mean")

    sums: dict = {}
    maxes: dict = {}
    counts: dict = {}
    degraded: dict = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        placed = _place_observation(
            obs, width, height, cell_size, tolerance, sums, maxes, counts, degraded, mode
        )
        if placed == "invalid":
            return {"ok": False, "error": "bad observation"}
        if placed == "rejected":
            rejected += 1
        elif placed == "dropped":
            dropped += 1
        elif placed == "saturated":
            saturated += 1

    total_cells = width * height
    cells = _value_rows(sums, maxes, counts, width, height, fill_value, mode)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, total_cells)
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    if not isinstance(raw["observations"], list):
        return "bad observations"
    mode = raw.get("mode", "mean")
    if mode not in ("mean", "max"):
        return "bad mode"
    return None


def _place_observation(
    obs: object,
    width: int,
    height: int,
    cell_size: int,
    tolerance: int,
    sums: dict,
    maxes: dict,
    counts: dict,
    degraded: dict,
    mode: str,
) -> str:
    if not isinstance(obs, dict):
        return "invalid"
    if not isinstance(obs.get("x"), int):
        return "invalid"
    if not isinstance(obs.get("y"), int):
        return "invalid"
    if not isinstance(obs.get("value"), int):
        return "invalid"
    if not isinstance(obs.get("quality"), int):
        return "invalid"
    quality = obs["quality"]
    if quality < 0 or quality > 100:
        return "invalid"

    if quality < MIN_QUALITY:
        return "rejected"

    x = obs["x"]
    if x < 0:
        return "dropped"
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return "dropped"

    y = obs["y"]
    if y < 0:
        return "dropped"
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return "dropped"

    key = (row, col)
    if counts.get(key, 0) >= SATURATION_LIMIT:
        return "saturated"
    if mode == "mean":
        sums[key] = sums.get(key, 0) + obs["value"]
    else:
        maxes[key] = max(maxes.get(key, obs["value"]), obs["value"])
    counts[key] = counts.get(key, 0) + 1
    if quality < GOOD_QUALITY:
        degraded[key] = True
    return "placed"


def _value_rows(sums: dict, maxes: dict, counts: dict, width: int, height: int, fill_value: int, mode: str) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                if mode == "mean":
                    cells.append(sums[key] // counts[key])
                else:
                    cells.append(maxes[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, total_cells: int) -> int:
    return len(counts) * 100 // total_cells


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

