from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    for check in (_payload_error, _grid_error, _inputs_error, _observation_error, _mode_error):
        if error := check(raw):
            return {"ok": False, "error": error}

    grid = raw["grid"]
    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    observations = raw["observations"]
    fill_value = raw["fill_value"]
    mode = raw.get("mode", "mean")

    cell_values: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    sums: dict[tuple[int, int], int] = {} if mode == "mean" else {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        x, y, value, quality = obs["x"], obs["y"], obs["value"], obs["quality"]
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        cell = _cell_for(x, y, cell_size, width, height, tolerance)
        if cell is None:
            dropped += 1
            continue

        if counts.get(cell, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue

        if mode == "max":
            cell_values[cell] = max(cell_values.get(cell, value), value)
        else:
            sums[cell] = sums.get(cell, 0) + value
        counts[cell] = counts.get(cell, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(cell)

    if mode == "max":
        cells = _value_rows(cell_values, counts, width, height, fill_value)
    else:
        cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _payload_error(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    return None


def _mode_error(raw: object) -> str | None:
    mode = raw.get("mode")
    if mode is not None and mode not in ("mean", "max"):
        return "bad mode"
    return None


def _grid_error(raw: dict) -> str | None:
    grid = raw["grid"]
    if not isinstance(grid, dict) or not _has_size_fields(grid):
        return "bad grid"
    if not _valid_dimension(grid["width"]):
        return "bad width"
    if not _valid_dimension(grid["height"]):
        return "bad height"
    if not isinstance(grid["cell_size"], int) or grid["cell_size"] < 1:
        return "bad cell size"
    return None


def _has_size_fields(grid: dict) -> bool:
    return "width" in grid and "height" in grid and "cell_size" in grid


def _valid_dimension(value: object) -> bool:
    return isinstance(value, int) and 1 <= value <= MAX_DIM


def _inputs_error(raw: dict) -> str | None:
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    if not isinstance(raw["observations"], list):
        return "bad observations"
    return None


def _observation_error(raw: dict) -> str | None:
    observations = raw["observations"]
    for obs in observations:
        if not isinstance(obs, dict):
            return "bad observation"
        if not all(isinstance(obs.get(name), int) for name in ("x", "y", "value", "quality")):
            return "bad observation"
        if obs["quality"] < 0 or obs["quality"] > 100:
            return "bad observation"
    return None


def _cell_for(
    x: int,
    y: int,
    cell_size: int,
    width: int,
    height: int,
    tolerance: int,
) -> tuple[int, int] | None:
    if x < 0 or y < 0:
        return None

    col = x // cell_size
    if col >= width:
        if x - width * cell_size >= tolerance:
            return None
        col = width - 1

    row = y // cell_size
    if row >= height:
        if y - height * cell_size >= tolerance:
            return None
        row = height - 1

    return row, col


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _value_rows(values: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(values[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

