_FIELD_CHECKS = {
    "id": lambda v: isinstance(v, str),
    "name": lambda v: isinstance(v, str) and bool(v),
    "age": lambda v: isinstance(v, int) and v >= 0,
    "email": lambda v: isinstance(v, str) and "@" in v,
    "phone": lambda v: isinstance(v, str) and len(v) == 10 and v.isdigit(),
}


def _invalid() -> dict:
    return dict(DEFAULT)


def _is_valid_record(raw: object) -> bool:
    if not isinstance(raw, dict):
        return False
    if not all(
        key in raw and _FIELD_CHECKS[key](raw[key]) for key in REQUIRED_KEYS
    ):
        return False
    return "phone" not in raw or _FIELD_CHECKS["phone"](raw["phone"])



def parse_record(raw: object) -> dict:
    if not _is_valid_record(raw):
        return _invalid()

    result = {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }
    if "phone" in raw:
        result["phone"] = raw["phone"]
