  const loyalty = req.loyaltyYears as number;
  const coupon = req.coupon as string;

  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minStay !== undefined && nights < spec.minStay) {
