const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const FORMATS = ["json", "yaml", "text"];
const LOG_LEVELS = ["debug", "info", "warn", "error"];

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    tag: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

interface FlagHandler {
  takesValue: boolean;
  apply(config: FlagConfig, value?: string): void;
}

const BOOLEAN_FLAGS: Record<string, (config: FlagConfig) => void> = {
  "--verbose": (c) => (c.verbose = true),
  "--quiet": (c) => (c.quiet = true),
  "--dry-run": (c) => (c.dryRun = true),
  "--force": (c) => (c.force = true),
  "--no-color": (c) => (c.color = false),
  "--strict": (c) => (c.strict = true),
};

const VALUE_FLAGS: Record<string, (config: FlagConfig, value: string) => void> = {
  "--output": (c, v) => (c.outputPath = v),
  "--config": (c, v) => (c.configPath = v),
  "--tag": (c, v) => (c.tag = v),
  "--format": (c, v) => {
    if (!FORMATS.includes(v)) {
      throw new Error(`unsupported format: ${v}`);
    }
    c.format = v;
  },
  "--log-level": (c, v) => {
    if (!LOG_LEVELS.includes(v)) {
      throw new Error(`unsupported log level: ${v}`);
    }
    c.logLevel = v;
  },
  "--retries": (c, v) => (c.maxRetries = parseInteger(v, "--retries")),
  "--timeout": (c, v) => (c.timeoutMs = parseInteger(v, "--timeout")),
  "--parallel": (c, v) => (c.parallelism = parseInteger(v, "--parallel")),
};

function parseInteger(value: string | undefined, flag: string): number {
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flag} must be an integer`);
  }
  return num;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const setBoolean = BOOLEAN_FLAGS[arg];
    if (setBoolean) {
