  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const booleanApply = BOOLEAN_FLAGS[arg];
    if (booleanApply) {
      booleanApply(config);
      continue;
    }
    if (arg in VALUE_FLAGS) {
      i = consumeValueFlag(config, arg, argv, i);
      continue;
    }
    throw new Error(`unknown flag: ${arg}`);
  }

  return config;
}

