        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return badId(index);
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return badQty(index);
      }
      const reservation = reserved[event.id];
      if (reservation === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reservation.qty) {
        shipped[event.id] = { item: reservation.item, qty: reservation.qty };
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reservation.qty) {
        reserved[event.id].qty = reservation.qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "return") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return badId(index);
      }
      const returning = shipped[event.id];
      if (returning === undefined) {
        rejected = rejected + 1;
      } else {
        stock[returning.item] = onHand(stock, returning.item) + returning.qty;
