interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  shippedItems: Record<string, Want>;
  queue: string[];
  rejected: number;
}

function onHand(state: State, item: string): number {
  return state.stock[item] === undefined ? 0 : state.stock[item];
}

function addStock(state: State, item: string, qty: number): void {
  state.stock[item] = onHand(state, item) + qty;
}

function takeStock(state: State, item: string, qty: number): void {
  state.stock[item] = onHand(state, item) - qty;
}

function reserve(state: State, id: string, want: Want): void {
  state.reserved[id] = want;
  state.orders[id] = "reserved";
}

function releaseHolding(state: State, id: string): void {
  const holding = state.reserved[id];
  addStock(state, holding.item, holding.qty);
  delete state.reserved[id];
}

function fulfillFromQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHandQty = onHand(state, want.item);
    if (onHandQty >= want.qty) {
      takeStock(state, want.item, want.qty);
      reserve(state, pendingId, want);
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qty = event.qty as number;
  if (!Number.isInteger(qty) || qty < 1) {
    return "event " + index + ": bad qty";
  }
  if (onHand(state, item) >= qty) {
    takeStock(state, item, qty);
    reserve(state, id, { item, qty });
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return undefined;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[id] !== undefined) {
    releaseHolding(state, id);
    state.orders[id] = "cancelled";
    fulfillFromQueue(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return "event " + index + ": bad qty";
  }
  if (state.reserved[id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[id].qty) {
    state.shippedItems[id] = { item: state.reserved[id].item, qty: state.reserved[id].qty };
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < state.reserved[id].qty) {
    state.reserved[id].qty = state.reserved[id].qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) {
    return "event " + index + ": bad item";
  }
  const qty = event.qty as number;
  if (!Number.isInteger(qty) || qty < 1) {
    return "event " + index + ": bad qty";
  }
  addStock(state, item, qty);
  fulfillFromQueue(state);
  return undefined;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[id] !== undefined) {
    releaseHolding(state, id);
    state.orders[id] = "expired";
    fulfillFromQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
}

function handleReturn(state: State, event: Record<string, unknown>, index: number): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return "event " + index + ": bad id";
  }
  const shipped = state.shippedItems[id];
  if (shipped === undefined) {
    state.rejected = state.rejected + 1;
  } else {
    addStock(state, shipped.item, shipped.qty);
    delete state.shippedItems[id];
    state.orders[id] = "returned";
    fulfillFromQueue(state);
  }
  return undefined;
}

const HANDLERS: Record<string, (state: State, event: Record<string, unknown>, index: number) => string | undefined> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function parseStock(raw: unknown): Record<string, number> | string {
  if (typeof raw !== "object" || raw === null) {
    return "bad stock";
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(raw as Record<string, unknown>)) {
    const value = (raw as Record<string, unknown>)[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return "bad stock";
    }
    stock[item] = value as number;
  }
  return stock;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = parseStock(input.stock);
  if (typeof stock === "string") {
    return { ok: false, error: stock };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    shippedItems: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(state, event, index);
    if (error !== undefined) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

