  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    state.stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const { orders, reserved, shipped, pendingWants, queue, stock } = state;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (onHand(stock, event.item) >= (event.qty as number)) {
        stock[event.item] = onHand(stock, event.item) - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        fillQueue(state);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        state.rejected = state.rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        state.rejected = state.rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        const before = shipped[event.id] === undefined ? 0 : shipped[event.id].qty;
        shipped[event.id] = {
          item: reserved[event.id].item,
          qty: before + reserved[event.id].qty,
        };
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        const before = shipped[event.id] === undefined ? 0 : shipped[event.id].qty;
        shipped[event.id] = {
          item: reserved[event.id].item,
          qty: before + (event.qty as number),
        };
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        state.rejected = state.rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      stock[event.item] = onHand(stock, event.item) + (event.qty as number);
      fillQueue(state);
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        fillQueue(state);
      } else {
        state.rejected = state.rejected + 1;
      }
    } else if (event.type === "return") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== "shipped" || shipped[event.id] === undefined) {
        state.rejected = state.rejected + 1;
      } else {
        const holding = shipped[event.id];
        stock[holding.item] = onHand(stock, holding.item) + holding.qty;
        delete shipped[event.id];
        orders[event.id] = "returned";
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected: state.rejected,
    report: buildReport(orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    if (counts[orders[id]] !== undefined) {
      counts[orders[id]] = counts[orders[id]] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  received: Record<string, Want>;
  queue: string[];
  rejected: number;
}

interface ParseResult {
  ok: boolean;
  error?: string;
  state?: State;
  events?: unknown[];
}

export function processEvents(raw: unknown): FulfillmentResult {
  const input = parseInput(raw);
  if (!input.ok) {
    return { ok: false, error: input.error };
  }
  const error = replay(input.state as State, input.events as unknown[]);
  if (error !== null) {
    return { ok: false, error };
  }
  return summarize(input.state as State);
}

type Handler = (state: State, event: Record<string, unknown>) => string | null;

const onHand = (state: State, item: string): number =>
  state.stock[item] === undefined ? 0 : state.stock[item];

function orderHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isId(event.id)) return "bad id";
  if (state.orders[event.id] !== undefined) return "duplicate order";
  if (!isItem(event.item)) return "bad item";
  if (!isQty(event.qty)) return "bad qty";

  state.received[event.id] = { item: event.item, qty: event.qty as number };
  if (onHand(state, event.item) >= (event.qty as number)) {
    state.stock[event.item] = onHand(state, event.item) - (event.qty as number);
    state.reserved[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    state.orders[event.id] = "backordered";
  }
  return null;
}

function cancelHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isId(event.id)) return "bad id";
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = onHand(state, holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "cancelled";
    fillBackorders(state);
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function shipHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isId(event.id)) return "bad id";
  if (event.qty !== undefined && !isQty(event.qty)) return "bad qty";
  if (state.reserved[event.id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[event.id].qty) {
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if ((event.qty as number) < state.reserved[event.id].qty) {
    state.reserved[event.id].qty = state.reserved[event.id].qty - (event.qty as number);
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function restockHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isItem(event.item)) return "bad item";
  if (!isQty(event.qty)) return "bad qty";
  state.stock[event.item] = onHand(state, event.item) + (event.qty as number);
  fillBackorders(state);
  return null;
}

function expireHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isId(event.id)) return "bad id";
  if (state.reserved[event.id] !== undefined) {
    const holding = state.reserved[event.id];
    state.stock[holding.item] = onHand(state, holding.item) + holding.qty;
    delete state.reserved[event.id];
    state.orders[event.id] = "expired";
    fillBackorders(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function returnHandler(state: State, event: Record<string, unknown>): string | null {
  if (!isId(event.id)) return "bad id";
  if (state.orders[event.id] !== "shipped") {
    state.rejected = state.rejected + 1;
  } else {
    const holding = state.received[event.id];
    state.stock[holding.item] = onHand(state, holding.item) + holding.qty;
    state.orders[event.id] = "returned";
    fillBackorders(state);
  }
  return null;
}

const handlers: Record<string, Handler> = {
  order: orderHandler,
  cancel: cancelHandler,
  ship: shipHandler,
  restock: restockHandler,
  expire: expireHandler,
  return: returnHandler,
};

const isId = (value: unknown): boolean =>
  typeof value === "string" && value.length > 0;
const isItem = (value: unknown): boolean =>
  typeof value === "string" && value.length > 0;
const isQty = (value: unknown): boolean =>
  Number.isInteger(value) && (value as number) >= 1;

function fillBackorders(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    if (onHand(state, want.item) >= want.qty) {
      state.stock[want.item] = onHand(state, want.item) - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function replay(state: State, events: unknown[]): string | null {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return "event " + index + ": malformed";
    }
    const handler = handlers[String((event as Record<string, unknown>).type)];
    if (!handler) {
      return "event " + index + ": bad type";
    }
    const error = handler(state, event as Record<string, unknown>);
    if (error !== null) {
      return "event " + index + ": " + error;
    }
  }
  return null;
}

function newState(stock: Record<string, number>): State {
  return {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    received: {},
    queue: [],
    rejected: 0,
  };
}

function parseStock(raw: unknown): Record<string, number> | null {
  if (typeof raw !== "object" || raw === null) {
    return null;
  }
  const stock: Record<string, number> = {};
  const rawStock = raw as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (rawStock[item] !== 0 && !isQty(rawStock[item])) {
      return null;
    }
    stock[item] = rawStock[item] as number;
  }
  return stock;
}

function parseInput(raw: unknown): ParseResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = parseStock(input.stock);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, state: newState(stock), events: input.events };
}

function summarize(state: State): FulfillmentResult {
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

