interface Want {
  item: string;
  qty: number;
}

interface State {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  orderData: Record<string, Want>;
  queue: string[];
  stock: Record<string, number>;
  rejected: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }

  const state: State = {
    orders: {},
    reserved: {},
    pendingWants: {},
    orderData: {},
    queue: [],
    stock: {},
    rejected: 0,
  };

  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    state.stock[item] = rawStock[item] as number;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const failed = handle(event, index, state);
    if (failed !== null) {
      return { ok: false, error: failed };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const HANDLERS: Record<
  string,
  (event: Record<string, unknown>, index: number, state: State) => string | null
> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const status = orders[id];
    if (counts[status] !== undefined) {
      counts[status] = counts[status] + 1;
    }
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function stockOnHand(state: State, item: string): number {
  return state.stock[item] === undefined ? 0 : state.stock[item];
}

function validateEventId(event: Record<string, unknown>, index: number): string | null {
  return isNonEmptyString(event.id) ? null : "event " + index + ": bad id";
}

function validateItem(event: Record<string, unknown>, index: number): string | null {
  return isNonEmptyString(event.item) ? null : "event " + index + ": bad item";
}

function validateQty(event: Record<string, unknown>, index: number): string | null {
  return isPositiveInt(event.qty) ? null : "event " + index + ": bad qty";
}

function handleOrder(event: Record<string, unknown>, index: number, state: State): string | null {
  const err =
    validateEventId(event, index) ??
    validateItem(event, index) ??
    validateQty(event, index);
  if (err !== null) {
    return err;
  }
  const id = event.id as string;
  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const item = event.item as string;
  const qty = event.qty as number;
  state.orderData[id] = { item, qty };
  if (stockOnHand(state, item) >= qty) {
    state.stock[item] = stockOnHand(state, item) - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function handleCancel(event: Record<string, unknown>, index: number, state: State): string | null {
  const err = validateEventId(event, index);
  if (err !== null) {
    return err;
  }
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = stockOnHand(state, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    satisfyQueue(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(event: Record<string, unknown>, index: number, state: State): string | null {
  const err = validateEventId(event, index);
  if (err !== null) {
    return err;
  }
  if (
    event.qty !== undefined &&
    (!Number.isInteger(event.qty) || (event.qty as number) < 1)
  ) {
    return "event " + index + ": bad qty";
  }
  const id = event.id as string;
  const holding = state.reserved[id];
  if (holding === undefined || (event.qty as number) > holding.qty) {
    state.rejected = state.rejected + 1;
    return null;
  }
  if (event.qty === undefined || (event.qty as number) === holding.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
    return null;
  }
  holding.qty = holding.qty - (event.qty as number);
  state.orders[id] = "partial";
  return null;
}

function handleRestock(event: Record<string, unknown>, index: number, state: State): string | null {
  const err = validateItem(event, index) ?? validateQty(event, index);
  if (err !== null) {
    return err;
  }
  const item = event.item as string;
  state.stock[item] = stockOnHand(state, item) + (event.qty as number);
  satisfyQueue(state);
  return null;
}

function handleReturn(event: Record<string, unknown>, index: number, state: State): string | null {
  const err = validateEventId(event, index);
  if (err !== null) {
    return err;
  }
  const id = event.id as string;
  if (state.orders[id] !== "shipped") {
    state.rejected = state.rejected + 1;
    return null;
  }
  const holding = state.orderData[id];
  state.stock[holding.item] = stockOnHand(state, holding.item) + holding.qty;
  state.orders[id] = "returned";
  return null;
}

function handleExpire(event: Record<string, unknown>, index: number, state: State): string | null {
  const err = validateEventId(event, index);
  if (err !== null) {
    return err;
  }
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = stockOnHand(state, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "expired";
    satisfyQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function satisfyQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const id = state.queue[position];
    const want = state.pendingWants[id];
    if (want === undefined) {
      continue;
    }
    const onHand = stockOnHand(state, want.item);
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

