interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  shipped: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Event = Record<string, unknown>;
type Outcome = { ok: true } | { ok: false; error: string };

const ok = (): Outcome => ({ ok: true });
const fail = (error: string): Outcome => ({ ok: false, error });

function isValidId(id: unknown): boolean {
  return typeof id === "string" && id.length > 0;
}

export function processEvents(raw: unknown): FulfillmentResult {
  const input = readInput(raw);
  if (!input.ok) {
    return { ok: false, error: input.error };
  }
  const state: State = {
    stock: input.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    shipped: {},
    queue: [],
    rejected: 0,
  };
  const events = input.events as Event[];
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const outcome = handler(event, state);
    if (!outcome.ok) {
      return { ok: false, error: "event " + index + ": " + outcome.error };
    }
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function readInput(
  raw: unknown
): { ok: true; stock: Record<string, number>; events: unknown[] } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return fail("malformed input");
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return fail("bad stock");
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return fail("bad stock");
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return fail("bad events");
  }
  return { ok: true, stock, events: input.events };
}

function handleOrder(event: Event, state: State): Outcome {
  if (!isValidId(event.id)) {
    return fail("bad id");
  }
  if (state.orders[event.id] !== undefined) {
    return fail("duplicate order");
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return fail("bad item");
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return fail("bad qty");
  }
  const item = event.item as string;
  const qty = event.qty as number;
  const available = state.stock[item] === undefined ? 0 : state.stock[item];
  if (available >= qty) {
    state.stock[item] = available - qty;
    state.reserved[event.id] = { item, qty };
    state.orders[event.id] = "reserved";
  } else {
    state.queue.push(event.id);
    state.pendingWants[event.id] = { item, qty };
    state.orders[event.id] = "backordered";
  }
  return ok();
}

function handleCancel(event: Event, state: State): Outcome {
  if (!isValidId(event.id)) {
    return fail("bad id");
  }
  if (state.reserved[event.id] !== undefined) {
    returnStock(state, event.id, state.reserved[event.id]);
    delete state.reserved[event.id];
    state.orders[event.id] = "cancelled";
    fulfillQueue(state);
  } else if (state.orders[event.id] === "backordered") {
    state.queue.splice(state.queue.indexOf(event.id), 1);
    delete state.pendingWants[event.id];
    state.orders[event.id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return ok();
}

function handleShip(event: Event, state: State): Outcome {
  if (!isValidId(event.id)) {
    return fail("bad id");
  }
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return fail("bad qty");
  }
  const holding = state.reserved[event.id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === holding.qty) {
    const amount = event.qty === undefined ? holding.qty : (event.qty as number);
    addShippedQty(state, event.id, holding.item, amount);
    delete state.reserved[event.id];
    state.orders[event.id] = "shipped";
  } else if ((event.qty as number) < holding.qty) {
    addShippedQty(state, event.id, holding.item, event.qty as number);
    holding.qty = holding.qty - (event.qty as number);
    state.orders[event.id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return ok();
}

function handleRestock(event: Event, state: State): Outcome {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return fail("bad item");
  }
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
    return fail("bad qty");
  }
  const held = state.stock[event.item] === undefined ? 0 : state.stock[event.item];
  state.stock[event.item] = held + (event.qty as number);
  fulfillQueue(state);
  return ok();
}

function handleExpire(event: Event, state: State): Outcome {
  if (!isValidId(event.id)) {
    return fail("bad id");
  }
  const holding = state.reserved[event.id];
  if (holding !== undefined) {
    returnStock(state, event.id, holding);
    delete state.reserved[event.id];
    state.orders[event.id] = "expired";
    fulfillQueue(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return ok();
}

function handleReturn(event: Event, state: State): Outcome {
  if (!isValidId(event.id)) {
    return fail("bad id");
  }
  const info = state.shipped[event.id];
  if (state.orders[event.id] !== "shipped" || info === undefined) {
    state.rejected = state.rejected + 1;
    return ok();
  }
  state.stock[info.item] = (state.stock[info.item] === undefined ? 0 : state.stock[info.item]) + info.qty;
  delete state.shipped[event.id];
  state.orders[event.id] = "returned";
  fulfillQueue(state);
  return ok();
}

const HANDLERS: Record<string, (event: Event, state: State) => Outcome> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
  return: handleReturn,
};

function returnStock(state: State, _id: string, holding: Want): void {
  state.stock[holding.item] =
    (state.stock[holding.item] === undefined ? 0 : state.stock[holding.item]) + holding.qty;
}

function addShippedQty(state: State, id: string, item: string, qty: number): void {
  if (state.shipped[id] === undefined) {
    state.shipped[id] = { item, qty };
  } else {
    state.shipped[id].qty = state.shipped[id].qty + qty;
  }
}

function fulfillQueue(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = state.stock[want.item] === undefined ? 0 : state.stock[want.item];
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

