import { processEvents } from "../process_events";

let pass = 0, fail = 0;
function check(name: string, input: unknown, expect: Partial<any>) {
  const r = processEvents(input);
  let e = "";
  if (r.ok !== expect.ok) e += `ok=${r.ok} `;
  if (expect.orders && JSON.stringify(r.orders) !== JSON.stringify(expect.orders)) e += `orders=${JSON.stringify(r.orders)} `;
  if (expect.stock && JSON.stringify(r.stock) !== JSON.stringify(expect.stock)) e += `stock=${JSON.stringify(r.stock)} `;
  if (expect.rejected !== undefined && r.rejected !== expect.rejected) e += `rejected=${r.rejected} `;
  if (expect.queue && JSON.stringify(r.queue) !== JSON.stringify(expect.queue)) e += `queue=${JSON.stringify(r.queue)} `;
  if (expect.report !== undefined && r.report !== expect.report) e += `report=${r.report} `;
  if (expect.error !== undefined && r.error !== expect.error) e += `error=${r.error} `;
  if (expect.type && r.orders && r.orders[expect.type.id] !== expect.type.val) e += `orders.${expect.type.id}=${r.orders?.[expect.type.id]} `;
  if (e) { fail++; console.log("FAIL", name, e); }
  else { pass++; }
}

